CREATE TABLE product_translations(product_id BIGINT NOT NULL,locale VARCHAR(10) NOT NULL,name VARCHAR(160) NOT NULL,brief VARCHAR(300) NOT NULL,description VARCHAR(2000) NOT NULL,PRIMARY KEY(product_id,locale),CONSTRAINT fk_product_translation FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
INSERT INTO product_translations(product_id,locale,name,brief,description) SELECT id,'zh-CN',CASE name WHEN 'Learning Laptop' THEN '学习笔记本电脑' WHEN 'Mechanical Keyboard' THEN '机械键盘' WHEN 'Developer Monitor' THEN '开发者显示器' WHEN 'USB-C Dock' THEN 'USB-C 扩展坞' WHEN 'Learning Headset' THEN '学习耳机' WHEN 'Spring Notebook' THEN 'Spring 笔记本' ELSE name END,CASE name WHEN 'Learning Laptop' THEN '适合编程实验的实用笔记本电脑' WHEN 'Mechanical Keyboard' THEN '适合长时间学习的舒适键盘' WHEN 'Developer Monitor' THEN '27 英寸 QHD 显示器' WHEN 'USB-C Dock' THEN '连接完整开发工作区' WHEN 'Learning Headset' THEN '在线课程专用耳机' WHEN 'Spring Notebook' THEN '记录架构与流程' ELSE brief END,CASE name WHEN 'Learning Laptop' THEN '用于 Java、Angular 和 Docker 学习的工作站。' WHEN 'Mechanical Keyboard' THEN '配备清晰段落感轴体的紧凑机械键盘。' WHEN 'Developer Monitor' THEN '可并排显示 IDE、终端和浏览器的清晰显示器。' WHEN 'USB-C Dock' THEN '提供显示、网络和 USB 连接的扩展坞。' WHEN 'Learning Headset' THEN '带麦克风的封闭式学习耳机。' WHEN 'Spring Notebook' THEN '用于记录流程、API 和数据库图的纸质笔记本。' ELSE description END FROM products;
